import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Тестирование и приёмка","description":"","frontmatter":{"pageId":"developers/testing","contentRevision":1},"headers":[],"relativePath":"ru/developers/testing.md","filePath":"ru/developers/testing.md"}'),l={name:"ru/developers/testing.md"};function o(n,e,s,c,d,h){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="тестирование-и-приемка" tabindex="-1">Тестирование и приёмка <a class="header-anchor" href="#тестирование-и-приемка" aria-label="Permalink to &quot;Тестирование и приёмка&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Сначала воспроизведи сценарий и увидь падающий целевой тест, затем минимальное исправление и повтор. Серверные тесты используют настоящий WebApplicationFactory; client-core тесты общаются с тестовым сервером. Полный набор: dotnet test Rimlink.sln -nologo -v q.</p><p>Поток Open вернулся — это ещё не peer attached: утверждай по полученным событиям. Таймауты измеряй Stopwatch, не DateTime.UtcNow. Для timing-изменений повтори набор на Linux/двух CPU при доступности среды.</p><p>Игровую логику проверяй двумя изолированными экземплярами host/guest, отдельными savedata и сервером/портом. BridgeTools/RimBridge — только доступный dev-инструмент, не зависимость релиза. Запиши фактически выполненные шаги и результат в manual checklist; сценарий сам по себе не является PASS.</p><p>Wiki: test:checks → check:content → check:reference → check:drift -- --base &lt;commit&gt; → build → check:links, затем реальный браузер/поиск/мобильная навигация.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Не запускай второй сервер на данных живого сервера и не останавливай чужую игру. Общий Player.log может перезаписываться экземплярами. Не называй незапущенный тест успешным.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./build">Сборка проекта</a></li><li><a href="./contributing">Вклад и сопровождение wiki</a></li><li><a href="./../admins/troubleshooting">Проблемы администратора</a></li></ul>',11)])])}const m=t(l,[["render",o]]);export{u as __pageData,m as default};
